<template><section class="mx-auto max-w-7xl px-4 py-14 sm:px-6 lg:px-8"><p class="text-sm uppercase tracking-[0.35em] text-cyan-200">Ticket Packages</p><h1 class="mt-4 text-5xl font-black">Choose how you will join the summit.</h1><div v-if="pending" class="mt-10 grid gap-5 md:grid-cols-2 xl:grid-cols-4"><div v-for="n in 4" :key="n" class="h-96 animate-pulse rounded-[2rem] bg-white/5" /></div><div v-else-if="error" class="mt-10 rounded-3xl border border-red-400/30 bg-red-950/30 p-6 text-red-100">Ticket packages could not be loaded. Please try again.</div><div v-else class="mt-10 grid gap-5 md:grid-cols-2 xl:grid-cols-4"><article v-for="ticket in tickets" :key="ticket.id" class="glass-card flex flex-col rounded-[2rem] p-7"><p class="text-sm text-cyan-200">{{ ticket.name }}</p><p class="mt-4 text-4xl font-black">{{ formatPrice(ticket.price,ticket.currency) }}</p><p class="mt-3 flex-1 text-sm leading-7 text-slate-400">{{ ticket.description }}</p><div class="mt-5 space-y-2 text-xs text-slate-400"><p>Capacity: {{ ticket.capacity }}</p><p>Sales end: {{ formatDate(ticket.sales_end_at) }}</p></div><NuxtLink :to="`/register?ticket=${ticket.id}`" class="mt-7 rounded-full bg-cyan-400 px-5 py-3 text-center font-semibold text-slate-950">Choose {{ ticket.name }}</NuxtLink></article></div><div class="mt-8 rounded-3xl border border-white/10 bg-white/5 p-6 text-sm leading-7 text-slate-300"><strong class="text-white">Ticket information:</strong> Availability and prices are loaded directly from the event backend. Registration is confirmed only after successful payment verification.</div></section></template>
<script setup lang="ts">import {useEvent} from '~/composables/useEvent'; useSeoMeta({title:'Tickets | ASEAN AI for Education',description:'Live ticket packages for the 2026 summit.'}); const {getEvents,getEventTicketTypes}=useEvent(); const {data:response,pending,error}=await useAsyncData('public-ticket-types',async()=>{const events=await getEvents(1,1); const event=events.data[0]; if(!event?.slug) throw new Error('Event not found'); return getEventTicketTypes(event.slug)}); const tickets=computed(()=>response.value?.data.filter(item=>item.is_active)??[]); const formatPrice=(price:number,currency:string)=>new Intl.NumberFormat('en-US',{style:'currency',currency,maximumFractionDigits:0}).format(price); const formatDate=(date?:string)=>date?new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'short',year:'numeric'}).format(new Date(date)):'Not specified';</script>
